m.sender_id,
m.client_message_id,
m.text,
m.created_at

FROM messages m

INNER JOIN message_sessions ms
ON ms.id = m.session_id

WHERE m.session_id = #{sessionId}

AND (
ms.customer_id = #{userId}
OR ms.agent_id = #{userId}
)


  AND m.id < #{beforeId}


